#include "r_smc_entry.h"

volatile uint32_t g_tau_interrupt_flag = 0;
volatile uint32_t blinkDelay = 500; // Initial blink delay of 0.5 second (on + off is 1Hz)
volatile uint32_t count = 0;/* use count to toggle alternatively 2 LEDs */

int main (void);

int main(void)
{
    EI();
    /* Start SW Interrupt */
    R_Config_INTC_INTP0_Start();

    /* Start TAU0 channel0 */
    R_Config_TAU0_0_Start();

    /* WAIT_LOOP */
    while (1) {

        while (0 == g_tau_interrupt_flag);

        g_tau_interrupt_flag = 0;
        count++;

        /* Write to the first LED pin */
        PIN_WRITE(LED1) = ~PIN_READ(LED1);

        if ((count % 2) == 0) {
            /* Write to the second LED pin */
            PIN_WRITE(LED2) = ~PIN_READ(LED2);
        }
    }

    return 0;
}
